#include "test_common.h"
#include "authentication.h"
static BmsUser_t make_user(void){BmsUser_t u;(void)memset(&u,0,sizeof u);u.userId=1U;(void)snprintf(u.username,sizeof u,"admin01");u.role=BMS_ROLE_ADMIN;u.status=BMS_USER_STATUS_ACTIVE;u.isActive=true;return u;}
static void test_auth_register_login(void){BmsAuthenticationContext_t c;BmsUser_t u=make_user(),out;ASSERT_STATUS(BMS_STATUS_OK,AuthenticationInitialize(&c));ASSERT_STATUS(BMS_STATUS_OK,AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_STATUS(BMS_STATUS_OK,AuthenticationLogin(&c,"admin01","Strong@123",&out));CU_ASSERT_EQUAL(out.userId,1U);CU_ASSERT_TRUE(AuthenticationHasRole(&out,BMS_ROLE_ADMIN));ASSERT_STATUS(BMS_STATUS_AUTHENTICATION_FAILED,AuthenticationLogin(&c,"admin01","Wrong@123",&out));AuthenticationDeinitialize(&c);}
static void test_auth_duplicate_next_id(void){BmsAuthenticationContext_t c;BmsUser_t u=make_user();BmsUserId_t id=0;AuthenticationInitialize(&c);AuthenticationRegisterUser(&c,&u,"Strong@123");ASSERT_STATUS(BMS_STATUS_ALREADY_EXISTS,AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_STATUS(BMS_STATUS_OK,AuthenticationGetNextUserId(&c,&id));CU_ASSERT_EQUAL(id,2U);CU_ASSERT_TRUE(AuthenticationAdministratorExists(&c));AuthenticationDeinitialize(&c);}
void RegisterAuthenticationTests(void){CU_pSuite s=CU_add_suite("Authentication",NULL,NULL);CU_add_test(s,"register and login",test_auth_register_login);CU_add_test(s,"duplicate and next id",test_auth_duplicate_next_id);}
